// Girdi: Konu sayısı
var videoCount = $('veri standartizasyonu3').first().json['KonuSayısı']; // Örn: 2 veya 3

if (!Number.isInteger(videoCount) || videoCount < 2) {
  throw new Error("KonuSayısı integer ve en az 2 olmalı.");
}

// ---- Sabit yollar ----
var base = "C:/Users/busra/OneDrive/Desktop/AlevPenceOtomasyonu/Proje";
var inputDir = base + "/VideoBölümler";
var finalPath = base + "/Final.mp4";

// ---- Giriş argümanları ----
var inputArgs = [];
for (var i = 1; i <= videoCount; i++) {
  inputArgs.push('-i "' + inputDir + '/output' + i + '.mp4"');
}

// ---- filter_complex oluşturma ----
var streams = "";
for (var j = 0; j < videoCount; j++) {
  streams += '[' + j + ':v:0][' + j + ':a:0]';
}
var filterComplex = streams + 'concat=n=' + videoCount + ':v=1:a=1[outv][outa]';

// ---- Map ve codec satırları ----
var mapLine   = '-map "[outv]" -map "[outa]"';
var codecLine = '-c:v libx264 -pix_fmt yuv420p -c:a aac -b:a 192k -movflags +faststart';

// ---- Tam komut ----
var ffmpegCommand =
  'ffmpeg ' + inputArgs.join(' ') + ' ' +
  '-filter_complex "' + filterComplex + '" ' +
  mapLine + ' ' + codecLine + ' "' + finalPath + '"';

// Çıktı
return [{ json: { ffmpegCommand: ffmpegCommand } }];

// n8n Function Item node
// Input ($json): { output: { KonuId, slides: [{ id, start_time, end_time }], totalSlides? } }
// Output: { KonuId: number, SlideCount: number, SaniyeBundle: number[] }

const out = $json.output ?? $json;
const slides = Array.isArray(out?.slides) ? out.slides : [];

const numFromId = (s) => {
  const m = String(s || "").match(/\d+/);
  return m ? Number(m[0]) : Number.POSITIVE_INFINITY;
};

const slidesSorted = [...slides].sort((a, b) => {
  const ta = Number(a?.start_time) || 0;
  const tb = Number(b?.start_time) || 0;
  if (ta !== tb) return ta - tb;
  return numFromId(a?.id) - numFromId(b?.id);
});

const SaniyeBundle = slidesSorted.map(s => {
  const start = Number(s?.start_time) || 0;
  const end = Number(s?.end_time) || 0;
  const dur = Math.max(0, end - start);
  return Number(dur.toFixed(3));
});

const KonuId = Number(out?.KonuId) || 0;
const SlideCount = slidesSorted.length;

return { KonuId, SlideCount, SaniyeBundle };

// n8n Code Node için—tek bir string içinde "[[start-end]]: sentence" formatında cümleleri ve ses süresini verir:

// 1) İlk input öğesinden words dizisini alın
const words = $input.first().json.words || [];

/* 
 * words dizisinden cümleleri start/end timestamp ile oluşturur.
 * @param {Array} words - [{ text, start, end, type, … }, …]
 * @returns {Array} sentences - [{ text, start, end }, …]
 */
function reconstructSentences(words) {
  const sentences = [];
  let currentText = '';
  let sentenceStart = null;

  for (const { text, start, end, type } of words) {
    if (type === 'word' || type === 'spacing') {
      if (sentenceStart === null && type === 'word') {
        sentenceStart = start;
      }
      currentText += text;
      if (text.includes('.')) {
        sentences.push({ text: currentText.trim(), start: sentenceStart, end });
        currentText = '';
        sentenceStart = null;
      }
    }
  }

  // Nokta ile bitmeyen son cümle varsa ekle
  if (currentText.trim()) {
    sentences.push({
      text: currentText.trim(),
      start: sentenceStart,
      end: words[words.length - 1].end,
    });
  }

  return sentences;
}

// 2) Cümleleri hesapla
const sentences = reconstructSentences(words);

// 3) Tek bir string oluştur: "[[start-end]]: sentence"
const result = sentences
  .map(s => `[[${s.start.toFixed(3)}-${s.end.toFixed(3)}]]: ${s.text}`)
  .join('\n');

// 4) Ses süresini hesapla
// Son cümlenin veya son kelimenin 'end' değeri
const lastEnd = sentences.length
  ? sentences[sentences.length - 1].end
  : (words.length ? words[words.length - 1].end : 0);
const audioDuration = Math.ceil(lastEnd + 1);

// 5) KonuId'yi doğrudan input'tan al
const KonuId = $('İçerik Üretimi1').first().json.output.KonuId ?? null;

// 6) Sonucu tek bir alan olarak döndür
return [
  {
    json: {
      result,
      audioDuration,
      KonuId
    },
  },
];

